package com.vocal.service;
import com.vocal.dto.AuthDtos.*; import com.vocal.entity.*; import com.vocal.enums.RoleName; import com.vocal.exception.ApiException; import com.vocal.repository.*; import com.vocal.security.JwtService; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.security.authentication.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class AuthService { private final UserRepository users; private final RoleRepository roles; private final PasswordEncoder encoder; private final JwtService jwt; private final AuthenticationManager auth; @Transactional public TokenResponse register(RegisterRequest r){ if(users.existsByEmail(r.email())) throw new ApiException(HttpStatus.CONFLICT,"Email already registered"); Role role=roles.findByName(RoleName.ROLE_CUSTOMER).orElseGet(()->roles.save(Role.builder().name(RoleName.ROLE_CUSTOMER).build())); User u=users.save(User.builder().email(r.email()).password(encoder.encode(r.password())).fullName(r.fullName()).phone(r.phone()).roles(new HashSet<>(Set.of(role))).build()); return issue(u);} public TokenResponse login(LoginRequest r){ auth.authenticate(new UsernamePasswordAuthenticationToken(r.email(),r.password())); return issue(users.findByEmail(r.email()).orElseThrow()); } private TokenResponse issue(User u){ var authorities=u.getRoles().stream().map(x->x.getName().name()).toList(); return new TokenResponse(jwt.access(u.getEmail(),authorities), jwt.refresh(u.getEmail()), new UserResponse(u.getId(),u.getEmail(),u.getFullName(),u.getPhone())); }}
